export type Accessor<T> = () => T;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (v: Prev) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export declare function createSignal<T>(value: Exclude<T, Function>): [Accessor<T>, (value: T) => T];
export declare function createOptimistic<T>(fn: ComputeFunction<T>): [Accessor<T>, (value: T) => T];
export declare function createEffect<const T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, effectFn: EffectFunction<NoInfer<T>, T>): void;
